+'use client';
+
+import { type ChangeEvent, type FormEvent, useCallback, useEffect, useMemo, useRef, useState } from 'react';
+import { Paperclip, Send, StopCircle } from 'lucide-react';
+import { useTranslations } from 'next-intl';
+import { toast } from 'sonner';
+
+import { Button } from '@/components/ui/button';
+import { Input } from '@/components/ui/input';
+import {
+  type ChatAttachment,
+  MAX_CHAT_ATTACHMENTS,
+  buildCanvasAttachmentsFromSelection,
+  resizeImageToDataUrl,
+} from '@/lib/chat-image-utils';
+import { useCanvasStore } from '@/store/canvas-store';
+import { useSelectionStore } from '@/store/selection-store';
+
+import { ChatImageAttachmentArea } from './chat-image-attachment-area';
+
+interface ChatFooterFormProps {
+  input: string;
+  handleInputChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
+  onSubmit: (e: React.FormEvent<HTMLFormElement>, attachments: ChatAttachment[]) => void;
+  isDisabled: boolean;
+  isProcessing: boolean;
+  onStop: () => void;
+}
+
+export function ChatFooterForm({
+  input,
+  handleInputChange,
+  onSubmit,
+  isDisabled,
+  isProcessing,
+  onStop
+}: ChatFooterFormProps) {
+  const t = useTranslations('Canvas.chat');
+  const [attachments, setAttachments] = useState<ChatAttachment[]>([]);
+  const fileInputRef = useRef<HTMLInputElement>(null);
+
+  const canSubmit = input.trim() !== '' || attachments.length > 0;
+
+  // Derive a stable key from the current image selection (sorted, comma-joined)
+  const selected = useSelectionStore((state) => state.selection.selected);
+  const canvasObjects = useCanvasStore((state) => state.canvasObjects);
+  const removeFromSelection = useSelectionStore((state) => state.removeFromSelection);
+
+  const selectedImageIdKey = useMemo(
+    () => selected.filter((s) => s.type === 'image').map((s) => s.id).sort().join(','),
+    [selected]
+  );
+
+  // Auto-sync canvas selection -> attachments (debounced 150ms)
+  useEffect(() => {
+    const timer = setTimeout(() => {
+      const currentSelected = useSelectionStore.getState().selection.selected;
+      setAttachments((prev) =>
+        buildCanvasAttachmentsFromSelection(currentSelected, canvasObjects, prev)
+      );
+    }, 150);
+    return () => clearTimeout(timer);
+  }, [selectedImageIdKey, canvasObjects]);
+
+  const addAttachment = useCallback(
+    (attachment: ChatAttachment) => {
+      setAttachments((prev) => {
+        if (prev.length >= MAX_CHAT_ATTACHMENTS) {
+          toast.error(t('imageAttachment.maxImagesReached', { max: String(MAX_CHAT_ATTACHMENTS) }));
+          return prev;
+        }
+        return [...prev, attachment];
+      });
+    },
+    [t]
+  );
+
+  const removeAttachment = useCallback((id: string, source?: 'canvas' | 'upload') => {
+    setAttachments((prev) => prev.filter((a) => a.id !== id));
+    // Also deselect from canvas selection if it was a canvas image
+    if (source === 'canvas') {
+      removeFromSelection(id);
+    }
+  }, [removeFromSelection]);
+
+  const handleFileSelect = useCallback(
+    async (e: ChangeEvent<HTMLInputElement>) => {
+      const files = e.target.files;
+      if (!files) return;
+
+      for (const file of Array.from(files)) {
+        if (!file.type.startsWith('image/')) {
+          toast.error(t('imageAttachment.invalidFileType'));
+          continue;
+        }
+
+        try {
+          const dataUrl = await resizeImageToDataUrl(file);
+          addAttachment({
+            id: crypto.randomUUID(),
+            name: file.name,
+            contentType: 'image/jpeg',
+            url: dataUrl,
+            source: 'upload',
+          });
+        } catch {
+          toast.error(t('imageAttachment.invalidFileType'));
+        }
+      }
+
+      if (fileInputRef.current) {
+        fileInputRef.current.value = '';
+      }
+    },
+    [addAttachment, t]
+  );
+
+  const handleFormSubmit = useCallback(
+    (e: FormEvent<HTMLFormElement>) => {
+      e.preventDefault();
+      if (!canSubmit) return;
+      onSubmit(e, attachments);
+      setAttachments([]);
+    },
+    [attachments, canSubmit, onSubmit]
+  );
+
+  return (
+    <div className="flex flex-col gap-1">
+      <ChatImageAttachmentArea attachments={attachments} onRemove={removeAttachment} />
+      <form onSubmit={handleFormSubmit} className="flex items-center space-x-2">
+        <input
+          ref={fileInputRef}
+          type="file"
+          accept="image/*"
+          multiple
+          className="hidden"
+          onChange={handleFileSelect}
+        />
+        <Button
+          type="button"
+          variant="ghost"
+          size="icon"
+          className="h-8 w-8 flex-shrink-0"
+          onClick={() => fileInputRef.current?.click()}
+          disabled={isDisabled || attachments.length >= MAX_CHAT_ATTACHMENTS}
+          title={t('imageAttachment.addImage')}
+        >
+          <Paperclip className="h-4 w-4" />
+        </Button>
+        <Input
+          value={input}
+          onChange={handleInputChange}
+          placeholder={t('placeholder')}
+          className="flex-1"
+          disabled={isDisabled}
+        />
+        {isProcessing ? (
+          <Button
+            type="button"
+            size="icon"
+            variant="destructive"
+            onClick={onStop}
+            title={t('stopGeneration')}
+          >
+            <StopCircle className="h-4 w-4" />
+          </Button>
+        ) : (
+          <Button type="submit" size="icon" disabled={!canSubmit}>
+            <Send className="h-4 w-4" />
+          </Button>
+        )}
+      </form>
+    </div>
+  );
+}
