+import type { ImageObject, CanvasObject } from '@/components/canvas/types';
+import { isImageObject } from '@/components/canvas/types';
+import { PLACEHOLDER_IMAGE_SRC } from '@/constants/canvas';
+import type { SelectionItem } from '@/hooks/use-selection-state';
+
+/**
+ * Represents an image attachment in the chat.
+ * - `source: 'canvas'` -- image from canvas (S3 URL, no resize needed)
+ * - `source: 'upload'` -- user file upload (resized to data URL)
+ */
+export interface ChatAttachment {
+  id: string; // unique ID for React keys and removal
+  name: string; // display name (filename or canvas object label)
+  contentType: string; // MIME type, e.g. 'image/jpeg'
+  url: string; // data URL (upload) or S3/CDN URL (canvas)
+  source: 'canvas' | 'upload';
+}
+
+/** Maximum number of image attachments per message */
+export const MAX_CHAT_ATTACHMENTS = 16;
+
+/** Maximum dimension (width or height) for resized uploads */
+const MAX_DIMENSION = 1024;
+
+/** JPEG quality for resized uploads */
+const JPEG_QUALITY = 0.7;
+
+/**
+ * Infer MIME content type from a URL's file extension.
+ * Defaults to 'image/jpeg' for unknown extensions.
+ */
+export function getContentTypeFromUrl(url: string): string {
+  const extension = url.split('.').pop()?.split('?')[0]?.toLowerCase();
+  switch (extension) {
+    case 'png':
+      return 'image/png';
+    case 'webp':
+      return 'image/webp';
+    case 'gif':
+      return 'image/gif';
+    default:
+      return 'image/jpeg';
+  }
+}
+
+/**
+ * Check whether an ImageObject src is a valid displayable image URL.
+ * Accepts http:, https:, data:, and blob: protocols.
+ */
+export function isValidImageSrc(src: string | string[] | undefined): boolean {
+  const resolved = Array.isArray(src) ? src[0] : src;
+  if (!resolved) return false;
+  try {
+    const parsed = new URL(resolved);
+    return ['http:', 'https:', 'data:', 'blob:'].includes(parsed.protocol);
+  } catch {
+    return false;
+  }
+}
+
+/**
+ * Convert a canvas ImageObject to a ChatAttachment.
+ * Handles `string | string[]` src (uses first element of array).
+ */
+export function imageObjectToAttachment(image: ImageObject): ChatAttachment {
+  const src = Array.isArray(image.src) ? image.src[0] : image.src;
+  const contentType = getContentTypeFromUrl(src);
+
+  return {
+    id: image.id,
+    name: image.userPrompt ?? 'Canvas image',
+    contentType,
+    url: src,
+    source: 'canvas',
+  };
+}
+
+/**
+ * Build the chat attachment list from the current canvas selection.
+ *
+ * 1. Filters selection to image items only
+ * 2. Looks up each image in canvasObjects, validates src
+ * 3. Merges with existing upload attachments (uploads first)
+ * 4. Truncates to MAX_CHAT_ATTACHMENTS
+ * 5. Returns same reference if result is identical (React optimization)
+ */
+export function buildCanvasAttachmentsFromSelection(
+  selectionItems: SelectionItem[],
+  canvasObjects: CanvasObject[],
+  currentAttachments: ChatAttachment[]
+): ChatAttachment[] {
+  // Build new canvas attachments from selection, skipping placeholder images
+  const newCanvasAttachments: ChatAttachment[] = [];
+  for (const item of selectionItems) {
+    if (item.type !== 'image') continue;
+    const obj = canvasObjects.find((o) => o.id === item.id);
+    if (!obj || !isImageObject(obj) || !isValidImageSrc(obj.src)) continue;
+    const src = Array.isArray(obj.src) ? obj.src[0] : obj.src;
+    if (src === PLACEHOLDER_IMAGE_SRC) continue;
+    newCanvasAttachments.push(imageObjectToAttachment(obj));
+  }
+
+  // Separate existing uploads from current attachments
+  const uploads = currentAttachments.filter((a) => a.source === 'upload');
+
+  // Combine: uploads first (priority), then canvas images, truncate to limit
+  const combined = [...uploads, ...newCanvasAttachments].slice(
+    0,
+    MAX_CHAT_ATTACHMENTS
+  );
+
+  // Referential equality check: if IDs and URLs match in order, return original reference
+  if (
+    combined.length === currentAttachments.length &&
+    combined.every((a, i) => a.id === currentAttachments[i].id && a.url === currentAttachments[i].url)
+  ) {
+    return currentAttachments;
+  }
+
+  return combined;
+}
+
+/**
+ * Resize an image File to a JPEG data URL.
+ * The longest side is capped at MAX_DIMENSION, aspect ratio preserved.
+ * Returns a data URL string (`data:image/jpeg;base64,...`).
+ *
+ * @param file - The image File from user input
+ * @returns Promise resolving to JPEG data URL
+ * @throws Error if file cannot be loaded as an image
+ */
+export function resizeImageToDataUrl(file: File): Promise<string> {
+  return new Promise((resolve, reject) => {
+    const img = new Image();
+    const objectUrl = URL.createObjectURL(file);
+
+    img.onload = () => {
+      URL.revokeObjectURL(objectUrl);
+
+      let { width, height } = img;
+
+      // Scale down if either dimension exceeds MAX_DIMENSION
+      if (width > MAX_DIMENSION || height > MAX_DIMENSION) {
+        const scale = MAX_DIMENSION / Math.max(width, height);
+        width = Math.round(width * scale);
+        height = Math.round(height * scale);
+      }
+
+      const canvas = document.createElement('canvas');
+      canvas.width = width;
+      canvas.height = height;
+
+      const ctx = canvas.getContext('2d');
+      if (!ctx) {
+        reject(new Error('Failed to get canvas 2d context'));
+        return;
+      }
+
+      ctx.drawImage(img, 0, 0, width, height);
+      const dataUrl = canvas.toDataURL('image/jpeg', JPEG_QUALITY);
+      resolve(dataUrl);
+    };
+
+    img.onerror = () => {
+      URL.revokeObjectURL(objectUrl);
+      reject(new Error(`Failed to load image: ${file.name}`));
+    };
+
+    img.src = objectUrl;
+  });
+}
