+import { describe, it, expect, beforeEach, vi } from 'vitest';
+
+import type { ImageObject, CanvasObject } from '@/components/canvas/types';
+import type { SelectionItem } from '@/hooks/use-selection-state';
+import { PLACEHOLDER_IMAGE_SRC } from '@/constants/canvas';
+
+import {
+  ChatAttachment,
+  MAX_CHAT_ATTACHMENTS,
+  getContentTypeFromUrl,
+  isValidImageSrc,
+  imageObjectToAttachment,
+  buildCanvasAttachmentsFromSelection,
+  resizeImageToDataUrl
+} from '@/lib/chat-image-utils';
+
+// ---------------------------------------------------------------------------
+// Mocks (for resizeImageToDataUrl browser-API tests)
+// ---------------------------------------------------------------------------
+
+let capturedOnload: (() => void) | null = null;
+let capturedOnerror: (() => void) | null = null;
+let capturedSrc: string | null = null;
+
+const mockImageInstance = {
+  set onload(fn: () => void) {
+    capturedOnload = fn;
+  },
+  set onerror(fn: () => void) {
+    capturedOnerror = fn;
+  },
+  set src(value: string) {
+    capturedSrc = value;
+  },
+  get src() {
+    return capturedSrc ?? '';
+  },
+  width: 0,
+  height: 0
+};
+
+vi.stubGlobal(
+  'Image',
+  vi.fn(function () { return mockImageInstance; })
+);
+
+const mockDrawImage = vi.fn();
+const mockToDataURL = vi.fn(() => 'data:image/jpeg;base64,mock');
+const mockGetContext = vi.fn();
+
+const mockCanvasElement = {
+  width: 0,
+  height: 0,
+  getContext: mockGetContext,
+  toDataURL: mockToDataURL
+};
+
+const originalCreateElement = document.createElement.bind(document);
+vi.spyOn(document, 'createElement').mockImplementation((tag: string) => {
+  if (tag === 'canvas') {
+    return mockCanvasElement as unknown as HTMLCanvasElement;
+  }
+  return originalCreateElement(tag);
+});
+
+const mockCreateObjectURL = vi.fn(() => 'blob:mock-url');
+const mockRevokeObjectURL = vi.fn();
+
+// Preserve the URL constructor (needed by isValidImageSrc) while mocking
+// createObjectURL / revokeObjectURL (needed by resizeImageToDataUrl).
+const OriginalURL = globalThis.URL;
+vi.stubGlobal('URL', Object.assign(
+  function UrlShim(input: string | URL, base?: string | URL) {
+    return new OriginalURL(input, base);
+  } as unknown as typeof URL,
+  {
+    ...OriginalURL,
+    prototype: OriginalURL.prototype,
+    createObjectURL: mockCreateObjectURL,
+    revokeObjectURL: mockRevokeObjectURL
+  }
+));
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+
+function createFakeFile(name: string): File {
+  return new File(['fake'], name, { type: 'image/png' });
+}
+
+/** Simulate the Image onload with the given natural dimensions. */
+function triggerLoad(width: number, height: number) {
+  mockImageInstance.width = width;
+  mockImageInstance.height = height;
+  capturedOnload!();
+}
+
+function triggerError() {
+  capturedOnerror!();
+}
+
+/** Build a minimal ImageObject for testing. */
+function makeImage(
+  overrides: Partial<ImageObject> & { id: string; src: string | string[] }
+): ImageObject {
+  return {
+    position: { x: 0, y: 0 },
+    width: 100,
+    height: 100,
+    type: 'image' as const,
+    ...overrides
+  };
+}
+
+/** Build a ChatAttachment for testing. */
+function makeUpload(id: string): ChatAttachment {
+  return {
+    id,
+    name: `upload-${id}.png`,
+    contentType: 'image/png',
+    url: `data:image/png;base64,${id}`,
+    source: 'upload'
+  };
+}
+
+// ---------------------------------------------------------------------------
+// Tests
+// ---------------------------------------------------------------------------
+
+describe('chat-image-utils', () => {
+  beforeEach(() => {
+    vi.clearAllMocks();
+    capturedOnload = null;
+    capturedOnerror = null;
+    capturedSrc = null;
+    mockGetContext.mockReturnValue({ drawImage: mockDrawImage });
+  });
+
+  // =========================================================================
+  // MAX_CHAT_ATTACHMENTS constant
+  // =========================================================================
+
+  it('MAX_CHAT_ATTACHMENTS is 16', () => {
+    expect(MAX_CHAT_ATTACHMENTS).toBe(16);
+  });
+
+  // =========================================================================
+  // getContentTypeFromUrl
+  // =========================================================================
